internal static async ValueTask<TResult> InspectAsync<TResult, TFactory>(InspectionReader r, ProbeReader? probe = null,
    ImageMetadataPolicy metadataPolicy = ImageMetadataPolicy.Strict)
    where TResult : struct where TFactory : struct, IInspectionResult<TResult>
{
    await r.ReadAsync(2).ConfigureAwait(false);
    if (r.Header[0] == 137 && r.Header[1] == 80)
    {
        await r.ReadAsync(6).ConfigureAwait(false);
        if (!r.Header.AsSpan(0, 6).SequenceEqual(PngCodec.Signature[2..])) throw new ImageDataException("Invalid PNG signature.");
        return await PngAsync<TResult, TFactory>(r, probe, metadataPolicy).ConfigureAwait(false);
    }
    if (r.Header[0] == 255 && r.Header[1] == 216) return await JpegAsync<TResult, TFactory>(r, probe, metadataPolicy).ConfigureAwait(false);
    if (r.Header[0] == 'R' && r.Header[1] == 'I')
    {
        await r.ReadAsync(10).ConfigureAwait(false);
        if (!r.Header.AsSpan(0, 2).SequenceEqual("FF"u8) || !r.Header.AsSpan(6, 4).SequenceEqual("WEBP"u8)) throw new ImageDataException("Invalid WebP RIFF header.");
        return await WebpAsync<TResult, TFactory>(r, BinaryPrimitives.ReadUInt32LittleEndian(r.Header.AsSpan(2)) + 8L, probe, metadataPolicy).ConfigureAwait(false);
    }
    throw new UnsupportedImageException(UnsupportedImageFeature.Format, "Expected a still PNG, JPEG or WebP image.");
}

internal static ValueTask<TResult> InspectAsync<TResult, TFactory>(InspectionReader r, ProbeReader? probe = null,
    ImageMetadataPolicy metadataPolicy = ImageMetadataPolicy.Strict)
    where TResult : struct where TFactory : struct, IInspectionResult<TResult>
{
    var prefix = r.ReadAsync(2);
    if (!prefix.IsCompletedSuccessfully) return AwaitInspectionPrefix<TResult, TFactory>(prefix, r, probe, metadataPolicy);
    prefix.GetAwaiter().GetResult();
    return AfterInspectionPrefix<TResult, TFactory>(r, probe, metadataPolicy);
}

[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
private static async ValueTask<TResult> AwaitInspectionPrefix<TResult, TFactory>(ValueTask prefix,
    InspectionReader r, ProbeReader? probe, ImageMetadataPolicy metadataPolicy)
    where TResult : struct where TFactory : struct, IInspectionResult<TResult>
{
    await prefix.ConfigureAwait(false);
    return await AfterInspectionPrefix<TResult, TFactory>(r, probe, metadataPolicy).ConfigureAwait(false);
}

private static ValueTask<TResult> AfterInspectionPrefix<TResult, TFactory>(InspectionReader r, ProbeReader? probe,
    ImageMetadataPolicy metadataPolicy)
    where TResult : struct where TFactory : struct, IInspectionResult<TResult>
{
    if (r.Header[0] == 137 && r.Header[1] == 80)
        return PngSignatureAsync<TResult, TFactory>(r, probe, metadataPolicy);
    if (r.Header[0] == 255 && r.Header[1] == 216)
        return JpegAsync<TResult, TFactory>(r, probe, metadataPolicy);
    if (r.Header[0] == 'R' && r.Header[1] == 'I')
        return WebpSignatureAsync<TResult, TFactory>(r, probe, metadataPolicy);
    throw new UnsupportedImageException(UnsupportedImageFeature.Format, "Expected a still PNG, JPEG or WebP image.");
}

private static async ValueTask<TResult> PngSignatureAsync<TResult, TFactory>(InspectionReader r, ProbeReader? probe,
    ImageMetadataPolicy metadataPolicy)
    where TResult : struct where TFactory : struct, IInspectionResult<TResult>
{
    await r.ReadAsync(6).ConfigureAwait(false);
    if (!r.Header.AsSpan(0, 6).SequenceEqual(PngCodec.Signature[2..])) throw new ImageDataException("Invalid PNG signature.");
    return await PngAsync<TResult, TFactory>(r, probe, metadataPolicy).ConfigureAwait(false);
}

private static async ValueTask<TResult> WebpSignatureAsync<TResult, TFactory>(InspectionReader r, ProbeReader? probe,
    ImageMetadataPolicy metadataPolicy)
    where TResult : struct where TFactory : struct, IInspectionResult<TResult>
{
    await r.ReadAsync(10).ConfigureAwait(false);
    if (!r.Header.AsSpan(0, 2).SequenceEqual("FF"u8) || !r.Header.AsSpan(6, 4).SequenceEqual("WEBP"u8)) throw new ImageDataException("Invalid WebP RIFF header.");
    return await WebpAsync<TResult, TFactory>(r, BinaryPrimitives.ReadUInt32LittleEndian(r.Header.AsSpan(2)) + 8L, probe, metadataPolicy).ConfigureAwait(false);
}
